  id: 'loan_1',
  item: BOOK,
  member: ADA,
  checkedOutOn: '2026-10-29',
  dueOn: '2026-11-19',
});

test('charges nothing for an item returned within the grace day', () => {
  assert.equal(assessLateFee({ loan, item: BOOK, member: ADA, returnedOn: '2026-11-20' }), 0);
});

